import { loadFont as loadMarcellus } from "@remotion/google-fonts/Marcellus";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// SÉRGIO · vídeo 2 (16/10): conforto do quarto + piscina incrível. Pedido pelo grupo de vendas, com 2 fotos (quarto e piscina,
// as mesmas do primeiro envio) → jeito "motion": tipografia cinética, ícones de traço e as duas fotos em cartão de destaque.
// Referências estudadas: GB House (imóvel: uma peça central por vez, ícone de traço) e Piscinou (palavra-chave num bloco de
// cor, ícone num anel, fundo alternando claro e escuro, onda de água).
// Identidade igual à do vídeo 1 (Sergio.tsx): grafite, off-white, madeira, bronze; Marcellus + Manrope. Abertura diferente
// do vídeo 1 (lá era o pino no mapa; aqui, a lua descendo: "terminar o dia").
// Locução: public/sergio/voz-v4.mp3 (Roberta, 22,9 s). Tempos = tempos da locução; o vídeo tem LEAD de entrada.

const { fontFamily: SERIF } = loadMarcellus("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadManrope("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const SQ_FPS = 30;
const LEAD = 0.3;
const VOICE_END = 22.85;
const END = 2.2;
export const SQ_FRAMES = Math.round((LEAD + VOICE_END + END) * SQ_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
// impulso curto da câmera quando um item entra (não fica balançando)
const bump = (t: number, a: number, d = 0.45) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const CHAR = "#1E1C1A";
const OFF = "#F3EFE8";
const WOOD = "#7A5534";
const BRONZE = "#C29A6B";
const WHITE = "#FFFFFF";
const WATER = "#2E7FA6";

const S = { quarto: 1.85, conforto: 8.65, calor: 11.55, piscina: 13.4, itajai: 17.15, cta: 20.35 };
const TR = 0.4;

type Trans = "up" | "split" | "diag" | "wave" | "zoom" | "left";

const Scene: React.FC<{ t: number; a: number; b: number; tr?: Trans; children: React.ReactNode }> = ({ t, a, b, tr, children }) => {
  if (t < a - 0.02 || t > b + TR + 0.05) return null;
  const p = tr ? io(t, a, a + TR + (tr === "wave" ? 0.25 : 0)) : 1;
  let style: React.CSSProperties = {};
  if (tr === "up") style = { transform: `translateY(${(1 - p) * 1920}px)` };
  if (tr === "left") style = { transform: `translateX(${(1 - p) * 1080}px)` };
  if (tr === "zoom") style = { transform: `scale(${1.35 - 0.35 * p})`, opacity: p };
  if (tr === "split") style = { clipPath: `inset(${(1 - p) * 50}% 0 ${(1 - p) * 50}% 0)` };
  if (tr === "diag") {
    const x = -1100 + p * 3300;
    style = { clipPath: `polygon(0 0, ${x}px 0, ${x - 1100}px 1920px, 0 1920px)` };
  }
  if (tr === "wave") {
    // água sobe com a borda ondulando
    const top = 2000 - p * 2200;
    const pts: string[] = [];
    for (let i = 0; i <= 24; i++) {
      const x = (i / 24) * 1080;
      pts.push(`${x}px ${top + Math.sin(i * 0.8 + t * 9) * 40 * (1 - p)}px`);
    }
    style = { clipPath: `polygon(${pts.join(", ")}, 1080px 1920px, 0 1920px)` };
  }
  return <AbsoluteFill style={{ ...style, overflow: "hidden" }}>{children}</AbsoluteFill>;
};

// palavra que entra com impulso e fica parada
const Word: React.FC<{ t: number; a: number; size: number; color: string; children: React.ReactNode; block?: string; blockText?: string }> = ({ t, a, size, color, children, block, blockText }) => {
  const s = pop(t, a, 0.5);
  if (block) {
    const w = k(t, a, 0.35);
    return (
      <div style={{ display: "inline-block", position: "relative", padding: `0 ${size * 0.22}px`, opacity: k(t, a, 0.2), transform: `scale(${0.8 + 0.2 * s})` }}>
        <div style={{ position: "absolute", left: 0, top: "8%", bottom: "4%", width: `${w * 100}%`, background: block, borderRadius: 14 }} />
        <span style={{ position: "relative", fontFamily: SERIF, fontSize: size, color: blockText ?? color, lineHeight: 1.15 }}>{children}</span>
      </div>
    );
  }
  return <div style={{ fontFamily: SERIF, fontSize: size, color, lineHeight: 1.1, opacity: k(t, a, 0.25), transform: `scale(${0.75 + 0.25 * s})` }}>{children}</div>;
};

const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 10, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap }}>{children}</div>
);

// ───────── ícones de traço ─────────
const ic = { fill: "none", stroke: BRONZE, strokeWidth: 5, strokeLinecap: "round", strokeLinejoin: "round" } as const;
const IconBed = () => (
  <g {...ic}>
    <path d="M8 44 V18 M8 34 H56 V44 M56 34 V28 Q56 24 52 24 H26 V34" />
    <rect x={12} y={22} width={11} height={8} rx={3} />
  </g>
);
const IconSnow = () => (
  <g {...ic}>
    <path d="M32 6 V58 M9.5 19 L54.5 45 M9.5 45 L54.5 19 M26 10 L32 16 L38 10 M26 54 L32 48 L38 54" />
  </g>
);
const IconSun = ({ r = 12 }: { r?: number }) => (
  <g {...ic}>
    <circle cx={32} cy={32} r={r} />
    {Array.from({ length: 8 }).map((_, i) => {
      const a = (i / 8) * Math.PI * 2;
      return <line key={i} x1={32 + Math.cos(a) * (r + 7)} y1={32 + Math.sin(a) * (r + 7)} x2={32 + Math.cos(a) * (r + 15)} y2={32 + Math.sin(a) * (r + 15)} />;
    })}
  </g>
);

const Chip: React.FC<{ t: number; a: number; icon: React.ReactNode; text: string }> = ({ t, a, icon, text }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 26, width: 640, padding: "20px 34px", borderRadius: 28, background: WHITE, boxShadow: "0 14px 34px rgba(30,28,26,0.12)", opacity: k(t, a, 0.25), transform: `scale(${0.7 + 0.3 * pop(t, a, 0.5)})` }}>
    <div style={{ width: 84, height: 84, borderRadius: 42, background: CHAR, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg width={56} height={56} viewBox="0 0 64 64">{icon}</svg>
    </div>
    <span style={{ fontFamily: SANS, fontWeight: 700, fontSize: 46, color: CHAR }}>{text}</span>
  </div>
);

const Ring: React.FC<{ t: number; a: number; size?: number; children: React.ReactNode }> = ({ t, a, size = 300, children }) => {
  const d = k(t, a, 0.7);
  const c = Math.PI * (size - 12);
  return (
    <div style={{ position: "relative", width: size, height: size, transform: `scale(${0.6 + 0.4 * pop(t, a, 0.6)})`, opacity: k(t, a, 0.2) }}>
      <svg width={size} height={size} style={{ position: "absolute", inset: 0, transform: "rotate(-90deg)" }}>
        <circle cx={size / 2} cy={size / 2} r={(size - 12) / 2} fill="none" stroke={BRONZE} strokeWidth={8} strokeDasharray={c} strokeDashoffset={c * (1 - d)} strokeLinecap="round" />
      </svg>
      <div style={{ position: "absolute", inset: 30, borderRadius: "50%", background: WOOD, display: "flex", alignItems: "center", justifyContent: "center" }}>{children}</div>
    </div>
  );
};

const PhotoCard: React.FC<{ src: string; t: number; a: number; b: number; w: number; h: number; s0: number; s1: number; ox?: string; dx?: number }> = ({ src, t, a, b, w, h, s0, s1, ox = "50% 50%", dx = 0 }) => {
  const p = io(t, a, b + TR);
  return (
    <div style={{ width: w, height: h, borderRadius: 34, overflow: "hidden", boxShadow: "0 30px 70px rgba(0,0,0,0.35)", transform: `scale(${0.85 + 0.15 * pop(t, a, 0.6)})`, opacity: k(t, a, 0.25) }}>
      <Img src={staticFile(`sergio/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${s0 + (s1 - s0) * p}) translateX(${dx * (p - 0.5)}px)`, transformOrigin: ox }} />
    </div>
  );
};

export const SergioQuarto: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / SQ_FPS - LEAD;

  // abertura: lua descendo no céu escuro ("terminar o dia")
  const moon = io(t, -LEAD, 1.4);
  const w1 = t < 0.72 ? 1 : 0; // "Imagina" some inteira antes de "terminar o dia"

  return (
    <AbsoluteFill style={{ background: CHAR }}>
      {/* 1 · Imagina terminar o dia */}
      <Scene t={t} a={-LEAD} b={S.quarto}>
        <AbsoluteFill style={{ background: CHAR, transform: `scale(${1.12 - 0.12 * io(t, -LEAD, S.quarto + TR)})` }}>
          <AbsoluteFill style={{ background: `radial-gradient(circle at 50% ${30 + 8 * moon}%, rgba(194,154,107,0.22) 0%, rgba(194,154,107,0) 40%)` }} />
          <svg viewBox="0 0 100 100" style={{ position: "absolute", left: 400, top: 380 + moon * 330, width: 280, height: 280, transform: `rotate(${-30 + 30 * moon}deg)` }}>
            <path d="M62 10 A42 42 0 1 0 90 66 A34 34 0 1 1 62 10 Z" fill={BRONZE} />
          </svg>
          <div style={{ position: "absolute", left: 120, right: 120, top: 1100, height: 340 }}>
            <div style={{ position: "absolute", inset: 0, display: "flex", justifyContent: "center", opacity: w1 }}>
              <Word t={t} a={0.0} size={170} color={WHITE}>Imagina</Word>
            </div>
            <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - w1 }}>
              <Word t={t} a={0.75} size={128} color={WHITE}>terminar</Word>
              <Word t={t} a={1.25} size={128} color={BRONZE}>o dia</Word>
            </div>
          </div>
        </AbsoluteFill>
      </Scene>

      {/* 2 · num quarto assim: foto em destaque + itens um por batida */}
      <Scene t={t} a={S.quarto} b={S.conforto} tr="up">
        <AbsoluteFill style={{ background: OFF, transform: `scale(${1.04 - 0.04 * io(t, S.quarto, S.conforto + TR) + 0.025 * (bump(t, 3.2) + bump(t, 4.5) + bump(t, 6.15))})` }}>
          <Col top={220}>
            <Word t={t} a={1.9} size={98} color={CHAR}>
              <span style={{ whiteSpace: "nowrap" }}>num quarto <span style={{ color: WOOD }}>assim</span></span>
            </Word>
          </Col>
          <div style={{ position: "absolute", left: 120, top: 420 }}>
            <PhotoCard src="quarto.jpg" t={t} a={2.05} b={S.conforto} w={840} h={680} s0={1.02} s1={1.3} ox="30% 22%" dx={70} />
          </div>
          <Col top={1160} gap={30}>
            <Chip t={t} a={3.2} icon={<IconBed />} text="Cama de casal" />
            <Chip t={t} a={4.5} icon={<IconSnow />} text="Ar-condicionado" />
            <Chip t={t} a={6.15} icon={<IconSun r={11} />} text="Luz natural" />
          </Col>
        </AbsoluteFill>
      </Scene>

      {/* 3 · Conforto pra descansar de verdade */}
      <Scene t={t} a={S.conforto} b={S.calor} tr="split">
        <AbsoluteFill style={{ background: CHAR, transform: `scale(${1 + 0.12 * io(t, S.conforto, S.calor + TR) + 0.025 * (bump(t, 9.5) + bump(t, 10.4))})` }}>
          <Col top={470} gap={80}>
            <Ring t={t} a={S.conforto + 0.05} size={380}>
              <svg width={200} height={200} viewBox="0 0 64 64" style={{ transform: `translateY(${-6 * Math.sin(lin(t, 9.4, 11.6) * Math.PI)}px)` }}>
                <g {...ic} stroke={OFF}>
                  <path d="M8 44 V18 M8 34 H56 V44 M56 34 V28 Q56 24 52 24 H26 V34" />
                  <rect x={12} y={22} width={11} height={8} rx={3} />
                </g>
              </svg>
            </Ring>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
              <Word t={t} a={8.8} size={140} color={CHAR} block={BRONZE} blockText={CHAR}>Conforto</Word>
              <Word t={t} a={9.5} size={96} color={WHITE}>pra descansar</Word>
              <Word t={t} a={10.4} size={96} color={WHITE}>de verdade</Word>
            </div>
          </Col>
        </AbsoluteFill>
      </Scene>

      {/* 4 · E quando bater o calor? sol crescendo */}
      <Scene t={t} a={S.calor} b={S.piscina} tr="diag">
        <AbsoluteFill style={{ background: OFF }}>
          <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 33%, rgba(194,154,107,${0.35 * k(t, 12.4, 0.8)}) 0%, rgba(194,154,107,0) 45%)` }} />
          <div style={{ position: "absolute", left: 540 - 240, top: 440, width: 480, height: 480, transform: `scale(${0.55 + 0.45 * pop(t, 11.6, 0.6) + 0.18 * io(t, 12.4, 13.6)}) rotate(${t * 22}deg)` }}>
            <svg width={480} height={480} viewBox="0 0 64 64">
              <circle cx={32} cy={32} r={12} fill={BRONZE} />
              <g {...ic} stroke={WOOD} strokeWidth={3}>
                {Array.from({ length: 12 }).map((_, i) => {
                  const a = (i / 12) * Math.PI * 2;
                  return <line key={i} x1={32 + Math.cos(a) * 17} y1={32 + Math.sin(a) * 17} x2={32 + Math.cos(a) * 26} y2={32 + Math.sin(a) * 26} />;
                })}
              </g>
            </svg>
          </div>
          <Col top={1090} gap={14}>
            <Word t={t} a={11.65} size={104} color={CHAR}>E quando bater</Word>
            <Word t={t} a={12.4} size={140} color={WHITE} block={WOOD}>o calor?</Word>
          </Col>
        </AbsoluteFill>
      </Scene>

      {/* 5 · piscina incrível no prédio (a água sobe e revela) */}
      <Scene t={t} a={S.piscina} b={S.itajai} tr="wave">
        <AbsoluteFill style={{ background: WATER }}>
          <AbsoluteFill style={{ background: "linear-gradient(180deg, #3A93BC 0%, #1F5F80 100%)" }} />
          <div style={{ position: "absolute", left: 150, top: 150 }}>
            <PhotoCard src="piscina.jpg" t={t} a={13.75} b={S.itajai} w={780} h={940} s0={1.04} s1={1.36} ox="50% 60%" dx={60} />
          </div>
          <Col top={1150} gap={16}>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 36, letterSpacing: "0.3em", color: OFF, opacity: k(t, 13.5, 0.3) }}>TEM UMA</div>
            <Word t={t} a={13.85} size={150} color={CHAR} block={OFF} blockText={WATER}>Piscina</Word>
            <Word t={t} a={14.27} size={110} color={WHITE}>incrível</Word>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 36, letterSpacing: "0.3em", color: OFF, opacity: k(t, 14.85, 0.3), marginTop: 6 }}>NO PRÉDIO</div>
          </Col>
        </AbsoluteFill>
      </Scene>

      {/* 6 · Itajaí, bairro São João */}
      <Scene t={t} a={S.itajai} b={S.cta} tr="zoom">
        <AbsoluteFill style={{ background: CHAR, transform: `scale(${1.08 - 0.08 * io(t, S.itajai, S.cta + TR)})` }}>
          <Col top={500} gap={40}>
            <svg width={300} height={340} viewBox="0 0 100 114">
              {(() => {
                const d = k(t, 17.2, 1.0);
                return (
                  <g fill="none" stroke={BRONZE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={600} strokeDashoffset={600 * (1 - d)}>
                    <path d="M14 110 V22 L50 6 L86 22 V110 Z M4 110 H96" />
                    {[0, 1, 2, 3, 4].map((r) => (
                      <path key={r} d={`M28 ${32 + r * 15} h12 M60 ${32 + r * 15} h12`} />
                    ))}
                    <path d="M42 110 V94 H58 V110" />
                  </g>
                );
              })()}
            </svg>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 38, letterSpacing: "0.3em", color: BRONZE, opacity: k(t, 17.35, 0.3) }}>APARTAMENTO EM</div>
            <Word t={t} a={17.95} size={180} color={WHITE}>Itajaí</Word>
            <Word t={t} a={18.8} size={84} color={OFF}>Bairro São João</Word>
          </Col>
        </AbsoluteFill>
      </Scene>

      {/* 7 · chamada: WhatsApp e CRECI */}
      <Scene t={t} a={S.cta} b={VOICE_END + END} tr="left">
        <AbsoluteFill style={{ background: OFF, transform: `scale(${1 + 0.06 * io(t, S.cta, VOICE_END + END)})` }}>
          <Col top={460} gap={50}>
            <Ring t={t} a={S.cta + 0.1} size={300}>
              <svg width={130} height={130} viewBox="0 0 64 64">
                <g {...ic} stroke={OFF}>
                  <rect x={10} y={14} width={44} height={40} rx={6} />
                  <path d="M10 26 H54 M22 8 V18 M42 8 V18" />
                  <path d="M24 40 L30 46 L42 33" strokeWidth={6} />
                </g>
              </svg>
            </Ring>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
              <Word t={t} a={21.65} size={120} color={CHAR}>Agende sua</Word>
              <Word t={t} a={21.95} size={120} color={WOOD}>visita</Word>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 22, padding: "24px 42px", borderRadius: 999, background: CHAR, opacity: k(t, 20.85, 0.3), transform: `scale(${0.75 + 0.25 * pop(t, 20.85, 0.55)})` }}>
              <svg width={64} height={64} viewBox="0 0 60 60">
                <path d="M30 4 A26 26 0 1 1 14 50 L5 55 L9 45 A26 26 0 0 1 30 4 Z" fill="#25D366" />
                <path d="M21 17 Q24 15 26 18 L28 23 Q28 25 26 27 Q29 33 34 35 Q36 33 38 33 L43 36 Q45 39 42 42 Q38 45 31 41 Q22 35 18 25 Q17 20 21 17 Z" fill={WHITE} />
              </svg>
              <span style={{ fontFamily: SANS, fontWeight: 700, fontSize: 60, color: WHITE }}>(00) 00000-0000</span>
            </div>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 36, letterSpacing: "0.3em", color: CHAR, opacity: k(t, 22.4, 0.35) }}>CRECI 18008</div>
          </Col>
        </AbsoluteFill>
      </Scene>
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { SQ_FPS, SQ_FRAMES, SergioQuarto } from "./SergioQuarto";

const Root: React.FC = () => (
  <>
    <Composition id="SergioQuarto" component={SergioQuarto} durationInFrames={SQ_FRAMES} fps={SQ_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
